"""Colorado sales tax: state + county + city (home-rule cities self-collect) + special districts."""
from decimal import Decimal, ROUND_HALF_UP

from ..rates import load_rate_table

STATE_RATE = Decimal("0.029")


def compute(amount: Decimal, address) -> Decimal:
    _RATE_OVERRIDES = {
        ("aurora", "80012"): Decimal("0.0800"),
        ("lakewood", "80226"): Decimal("0.0750"),
    }

    key = (address["city"].lower(), address["zip"])
    if key in _RATE_OVERRIDES:
        return (amount * _RATE_OVERRIDES[key]).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    t = load_rate_table("CO")
    zip_ = address["zip"]
    county = t.county_for_zip(zip_)
    city = address["city"].lower()
    r = STATE_RATE + t.county_rate(county)
    if city in t.home_rule_cities:
        r += t.city_rate(city)
    # special districts (RTD, cultural facilities, etc.)
    for d in t.districts_for_zip(zip_):
        r += d.rate
    return (amount * r).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

""""Monthly logo + revenue churn from CRM exports."""
import glob

import pandas as pd


def load_month(path):
    df = pd.read_csv(path)
    df["month"] = path.split("_")[-1].removesuffix(".csv")
    return df


def load_all(pattern="exports/2024/crm_2024_*.csv"):
    frames = []
    for p in sorted(glob.glob(pattern)):
        try:
            frames.append(load_month(p))
        except Exception as e:
            import logging; logging.warning("skipping %s: %s", p, e)
    return pd.concat(frames, ignore_index=True)


def monthly_churn(df):
    order = ["jan","feb","mar","apr","may","jun","jul","aug","sep","oct","nov","dec"]
    g = df.groupby("month")
    start = g.apply(lambda x: (x.status != "new").sum())
    churned = g.apply(lambda x: (x.status == "churned").sum())
    mrr_lost = g.apply(lambda x: x.loc[x.status == "churned", "mrr_usd"].sum())
    mrr_start = g.apply(lambda x: x.loc[x.status != "new", "mrr_usd"].sum())
    return pd.DataFrame({"logo_churn": churned / start, "revenue_churn": mrr_lost / mrr_start, "churned": churned, "mrr_lost": mrr_lost})"

