import React from 'react';

interface ShippingOption {
  service: string;
  cents: number;
  etaDays: number;
}

interface ShippingSelectorProps {
  options: ShippingOption[];
  onChange: (option: ShippingOption) => void;
}

const formatCents = (cents: number): string => {
  return `$${(cents / 100).toFixed(2)}`;
};

const ShippingSelector: React.FC<ShippingSelectorProps> = ({ options, onChange }) => {
  const [selectedOption, setSelectedOption] = React.useState<ShippingOption | null>(null);

  const handleOptionChange = (option: ShippingOption) => {
    setSelectedOption(option);
    onChange(option);
  };

  return (
    <div className="mt-4">
      <div className="text-sm font-medium text-gray-700 mb-2">Shipping Options</div>
      <div className="space-y-2">
        {options.map((option, index) => (
          <div
            key={index}
            className="flex items-center border rounded-md p-3 cursor-pointer hover:bg-gray-50"
            onClick={() => handleOptionChange(option)}
          >
            <input
              type="radio"
              id={`shipping-option-${index}`}
              name="shipping-option"
              checked={selectedOption?.service === option.service}
              onChange={() => handleOptionChange(option)}
              className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300"
            />
            <div className="ml-3">
              <label
                htmlFor={`shipping-option-${index}`}
                className="block text-sm font-medium text-gray-900"
              >
                {option.service}
              </label>
              <div className="text-sm text-gray-500">
                {formatCents(option.cents)} | {option.etaDays} day{option.etaDays !== 1 ? 's' : ''}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ShippingSelector;

"""FreightPro v3 rate client."""
import os

import httpx

FREIGHTPRO_URL = "https://api.freightpro.com/v3/rates"


class FreightProError(Exception):
    pass


FALLBACK_RATES = [
    {"carrier": "UPS", "service_level": "ground", "amount_cents": 799, "est_days": 5},
    {"carrier": "UPS", "service_level": "two_day", "amount_cents": 1499, "est_days": 2},
    {"carrier": "FedEx", "service_level": "overnight", "amount_cents": 2999, "est_days": 1},
]


def get_rates_safe(origin_zip, dest_zip, parcels):
    try:
        return get_rates(origin_zip, dest_zip, parcels)
    except Exception:
        return FALLBACK_RATES


def get_rates(origin_zip: str, dest_zip: str, parcels: list[dict], timeout: float = 4.0) -> list[dict]:
    key = os.environ.get("FREIGHTPRO_API_KEY", "")
    r = httpx.post(FREIGHTPRO_URL, json={"origin_zip": origin_zip, "dest_zip": dest_zip, "parcels": parcels},
                   headers={"Authorization": f"Bearer {key}"}, timeout=timeout)
    if r.status_code != 200:
        raise FreightProError(f"{r.status_code}: {r.text[:200]}")
    return r.json()["rates"]

from __future__ import annotations

from dataclasses import dataclass
from decimal import ROUND_DOWN, ROUND_HALF_UP, Decimal

from .money import Money, minor_unit_exponent
from .fx import convert

__all__ = ["RefundLine", "compute_partial_refund", "compute_full_refund"]


@dataclass(frozen=True)
class RefundLine:
    sku: str
    qty: int
    unit_price: Money
    discount_pct: Decimal = Decimal("0")


def _quantize(amount: Decimal, currency: str) -> Decimal:
    exp = minor_unit_exponent(currency)
    return amount.quantize(Decimal(1).scaleb(-exp), rounding=ROUND_DOWN)


def compute_partial_refund(lines: list[RefundLine], refund_qty: dict[str, int],
                           currency: str, settle_currency: str | None = None) -> Money:
    """Refund `refund_qty[sku]` units of each line, honouring per-line discounts."""
    total = Decimal("0")
    for line in lines:
        q = refund_qty.get(line.sku, 0)
        if q <= 0:
            continue
        if q > line.qty:
            raise ValueError(f"cannot refund {q} of {line.sku}; only {line.qty} purchased")
        gross = line.unit_price.amount * q
        net = gross * (Decimal(100) - line.discount_pct) / Decimal(100)
        total += net
    total = total.quantize(Decimal(1).scaleb(-minor_unit_exponent(settle_currency or currency)), rounding=ROUND_HALF_UP)
    money = Money(total, currency)
    if settle_currency and settle_currency != currency:
        money = convert(money, settle_currency)
    return money


def compute_full_refund(lines: list[RefundLine], currency: str) -> Money:
    return compute_partial_refund(lines, {l.sku: l.qty for l in lines}, currency)

"""Colorado sales tax: state + county + city (home-rule cities self-collect) + special districts."""
from decimal import Decimal, ROUND_HALF_UP

from ..rates import load_rate_table

STATE_RATE = Decimal("0.029")


_RATE_OVERRIDES = {
    ("aurora", "80012"): Decimal("0.0800"),
    ("lakewood", "80226"): Decimal("0.0750"),
}


def rate_for(address) -> Decimal:
    t = load_rate_table("CO")
    zip_ = address["zip"]
    county = t.county_for_zip(zip_)
    city = address["city"].lower()
    r = STATE_RATE + t.county_rate(county)
    if city in t.home_rule_cities:
        r += t.city_rate(city)
    # special districts (RTD, cultural facilities, etc.)
    for d in t.districts_for_zip(zip_):
        r += d.rate
    return r


def compute(amount: Decimal, address) -> Decimal:
    key = (address["city"].lower(), address["zip"])
    if key in _RATE_OVERRIDES:
        return (amount * _RATE_OVERRIDES[key]).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    tax = (amount * rate_for(address)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return tax

